import re

def _safe_float(value):
    if value is None:
        return None
    text = str(value).strip().replace('.', '').replace(',', '.')
    match = re.search(r'[-+]?[0-9]*\.?[0-9]+', text)
    if not match:
        return None
    try:
        return float(match.group(0))
    except Exception:
        return None

def _extract_rate(exchange_rate_response):
    if hasattr(exchange_rate_response, 'root'):
        exchange_rate_response = exchange_rate_response.root

    if isinstance(exchange_rate_response, dict) and 'root' in exchange_rate_response:
        exchange_rate_response = exchange_rate_response['root']

    if isinstance(exchange_rate_response, dict) and 'rawExchangeRateResponse' in exchange_rate_response:
        exchange_rate_response = exchange_rate_response['rawExchangeRateResponse']

    if isinstance(exchange_rate_response, list) and exchange_rate_response:
        first = exchange_rate_response[0]
    else:
        first = exchange_rate_response

    if hasattr(first, 'root'):
        first = first.root

    if isinstance(first, dict) and 'root' in first:
        first = first['root']

    if isinstance(first, dict) and 'rawExchangeRateResponse' in first:
        nested = first['rawExchangeRateResponse']
        if isinstance(nested, list) and nested:
            first = nested[0]
        else:
            first = nested

    for key in ['srednji_tecaj', 'kupovni_tecaj', 'prodajni_tecaj']:
        value = None
        if isinstance(first, dict):
            value = first.get(key)
        elif hasattr(first, key):
            value = getattr(first, key)
        rate = _safe_float(value)
        if rate is not None:
            return rate

    return None

def perform(input, context):
    exchange_rate_response = input.exchangeRateResponse
    catalog_html = input.catalogHtml

    usd_per_eur_current = _extract_rate(exchange_rate_response)
    if not usd_per_eur_current:
        return {
            'error': 'Could not extract USD exchange rate from HNB response.',
            'rawExchangeRateResponse': exchange_rate_response
        }

    usd_per_eur_2025 = _extract_rate(catalog_html)
    if not usd_per_eur_2025:
        return {
            'error': 'Could not extract USD exchange rate from HNB response.',
            'rawExchangeRateResponse': catalog_html
        }



    return {
        'usdPerEurCur': usd_per_eur_current,
        'usdPerEur2025': usd_per_eur_2025,
        'diff': usd_per_eur_current - usd_per_eur_2025
    }
